+++ b/tests/sites.test.js
@@ -0,0 +1,75 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const annex = { "x-larder-site": "annex" };
+
+// Puts 3 kg of onion (item 1) into the annex fridge through an order.
+async function stockAnnex(handle) {
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  return handle({ method: "POST", path: `/orders/${order.id}/receive`, headers: annex, body: { lots: [{ lot: "AN-1", expires: "2026-10-30", location: "annex-fridge" }] } });
+}
+
+test("the seed has the annex site and fridge", () => {
+  const { store } = app();
+  assert.deepEqual(store.data.sites.map((s) => s.id), ["main", "annex"]);
+  assert.equal(store.data.locations.find((l) => l.id === "annex-fridge").site, "annex");
+  assert.ok(store.data.locations.filter((l) => l.id !== "annex-fridge").every((l) => l.site === "main"));
+});
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "X-Larder-Site": "nowhere" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /nowhere/);
+});
+
+test("without the header the site is main", async () => {
+  const { handle } = app();
+  const plain = await handle({ path: "/items" });
+  const main = await handle({ path: "/items", headers: { "x-larder-site": "main" } });
+  assert.deepEqual(plain.body, main.body);
+  assert.equal(plain.body.find((i) => i.id === 1).onHand, 10);
+});
+
+test("annex stock is separate from main", async () => {
+  const { handle } = app();
+  assert.equal((await stockAnnex(handle)).status, 200);
+  const at = async (headers, path) => (await handle({ path, headers })).body;
+  assert.equal((await at(annex, "/items")).find((i) => i.id === 1).onHand, 3);
+  assert.equal((await at({}, "/items")).find((i) => i.id === 1).onHand, 10);
+  assert.deepEqual((await at(annex, "/batches")).map((b) => b.lot), ["AN-1"]);
+  assert.ok((await at({}, "/batches")).every((b) => b.lot !== "AN-1"));
+  assert.equal((await at(annex, "/reports/stock-value")).lines.find((l) => l.itemId === 1).qty, 3);
+  assert.deepEqual((await at(annex, "/alerts")).expiring.map((b) => b.lot), ["AN-1"]);
+  assert.ok((await at({}, "/alerts")).expiring.every((b) => b.lot !== "AN-1"));
+});
+
+test("receiving into another site's location is refused", async () => {
+  const { handle } = app();
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, body: { lots: [{ lot: "x", expires: null, location: "annex-fridge" }] } });
+  assert.equal(res.body.error.code, "unknown_location");
+});
+
+test("cooking only uses the site's own stock", async () => {
+  const { handle, store } = app();
+  await stockAnnex(handle);
+  const before = JSON.stringify(store.data.batches.filter((b) => b.lot !== "AN-1"));
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 4 } });
+  assert.equal(res.status, 409);
+  assert.equal(JSON.stringify(store.data.batches.filter((b) => b.lot !== "AN-1")), before);
+});
+
+test("stock-takes stay within their site", async () => {
+  const { handle } = app();
+  const bad = await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" } });
+  assert.equal(bad.body.error.code, "unknown_location");
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "annex-fridge" } })).body;
+  const other = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` });
+  assert.equal(other.status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: annex })).status, 200);
+});
